window.HIKAYELER = [
  { id: "k01", baslik: "Kırmızı Şemsiye", resim: "☂️ 🌧️ 😊", ders: "Paylaşmak dostluğu büyütür.",
    sayfalar: [
      "Okul çıkışında birden yağmur başladı. Zeynep çantasından kırmızı şemsiyesini çıkardı.",
      "Okulun bahçesindeki çocuklar koşarak saçakların altına kaçıyordu. Kimi montunun başlığını takmış, kimi annesinin şemsiyesine sığınmıştı. Su birikintileri her yerde küçük göllere dönüşmüştü. Zeynep şemsiyesini açınca kırmızı bir çiçek gibi parladı.",
      "Emre'nin ayakkabıları su almıştı. Her adımda çıt çıt diye ses çıkarıyordu. Montu ıslandıkça ağırlaşıyordu. Diğer çocuklar velileriyle birer birer gidiyordu. Okulun önünde Emre'den başka kimse kalmamıştı. Zeynep onu uzaktan görünce durdu.",
      "Kapının önünde Emre bekliyordu. Emre'nin şemsiyesi yoktu ve saçları ıslanmıştı.",
      "Emre çantasını başının üstüne koymuştu. \"Annem bugün işte, beni almaya kimse gelemedi.\" dedi. Sesi biraz titriyordu.",
      "Zeynep bir an düşündü. Annesi her sabah ona, \"Birine yardım edebiliyorsan hiç bekleme,\" derdi. Emre'nin ıslak saçlarından damlalar süzülüyordu. Zeynep'in içi ona çok acıdı. Şemsiyesini biraz daha yükseğe kaldırdı.",
      "Zeynep, \"Gel, şemsiyemin altına gir. Evlerimiz aynı yolda.\" dedi.",
      "Şemsiye küçüktü ama ikisi omuz omuza yürüyünce sığdılar. Yağmur damlaları şemsiyenin üstünde davul çalıyordu.",
      "Yolda bir su birikintisinin önüne geldiler. Emre, \"Atlayalım mı?\" diye sordu. İkisi birden \"Bir, iki, üç!\" deyip atladılar. Şap diye suya bastılar ve kahkahalarla güldüler. Ayakkabıları ıslanmıştı ama hiç umursamadılar.",
      "İkisi şarkı söyleyerek yürüdüler. O günden sonra yağmurlu günleri çok sevdiler.",
      "Emre'nin evinin önüne geldiklerinde annesi de işten yeni dönmüştü. Kadın Zeynep'e sarıldı. \"Oğluma yardım ettiğin için çok teşekkür ederim,\" dedi. Ertesi gün Emre okula iki şemsiye getirdi. Birini Zeynep'e uzattı: \"Bu yedek. Bir gün başka birine lazım olur.\""
    ],
    sorular: [["Zeynep'in şemsiyesi ne renkti?","Kırmızı",["Mavi","Sarı"]],["Emre neden ıslanmıştı?","Şemsiyesi yoktu",["Havuza düşmüştü","Su içmişti"]],["Çocuklar yolda ne yaptı?","Şarkı söyledi",["Koştu","Ağladı"]],["Emre'yi neden kimse almaya gelemedi?","Annesi işteydi",["Okul kapalıydı","Hasta olmuştu"]]] },
  { id: "k02", baslik: "Minik Fidan", resim: "🌱 💧 🌳", ders: "Emek verdiğimiz şeyler büyür.",
    sayfalar: [
      "Can'ın sınıfı okul bahçesine bir fidan dikti. Fidan çok küçüktü.",
      "Fidanın ince bir gövdesi ve birkaç küçük yaprağı vardı. Rüzgâr estiğinde bir o yana bir bu yana eğiliyordu. Öğretmen fidanın yanına bir sopa çaktı ve gövdesini yumuşak bir iple sopaya bağladı. \"Bu ona destek olacak,\" dedi.",
      "Öğretmenleri, \"Bu fidan büyüyüp ağaç olacak. Ama önce bizim sevgimize ve emeğimize ihtiyacı var.\" dedi. Çocuklar fidanın etrafına küçük taşlar dizdiler.",
      "Her sabah sırayla fidanı suladılar. Can da sulama gününü hiç unutmadı.",
      "Bir gün çok sıcak bir hava oldu. Toprak çatlamıştı. Can okul çıkışı fidanın yapraklarının büzüldüğünü gördü. Hemen bir kova su getirdi. Fidanın dibine yavaş yavaş döktü. Yapraklar sanki ona teşekkür eder gibi yeniden açıldı.",
      "Kış gelince fidanın yaprakları döküldü. Bazı çocuklar, \"Fidan kurudu!\" diye üzüldü. Öğretmen, \"Hayır, sadece kış uykusunda.\" dedi.",
      "Bahar gelince fidanın dallarında yeşil yapraklar çıktı.",
      "Kış boyunca çocuklar fidanı hiç unutmadı. Kar yağdığında üstündeki karları silkelediler. Sert rüzgârlarda ipini kontrol ettiler. Can, \"Uyuyan birine de iyi bakılır,\" diyordu. Arkadaşları ona gülümseyerek hak verdi.",
      "Yıllar sonra Can ve arkadaşları ortaokula başladı. Bir gün eski okullarını ziyaret ettiler. Bahçedeki elma ağacı kocaman olmuştu. Dallarında kırmızı elmalar vardı. Yeni birinci sınıflar ağacın gölgesinde kitap okuyordu. Can'ın gözleri doldu ve gülümsedi.",
      "Can, \"Bir gün bu ağacın gölgesinde kitap okuyacağız.\" dedi. Arkadaşları alkışladı.",
      "İlkbaharın sonunda fidanın dallarında beyaz çiçekler açtı. Bu bir elma ağacıydı! Arılar vızıldayarak çiçeklere kondu. Öğretmen, \"Belki birkaç yıl sonra bu ağaçtan elma toplayacaksınız,\" dedi. Çocuklar sevinçle zıpladı."
    ],
    sorular: [["Çocuklar bahçeye ne dikti?","Fidan",["Çiçek","Havuç"]],["Fidanı ne zaman sularlardı?","Her sabah",["Hiç","Yılda bir"]],["Baharda ne oldu?","Yapraklar çıktı",["Fidan kurudu","Kar yağdı"]],["Kışın fidana ne oldu?","Yaprakları döküldü",["Çiçek açtı","Meyve verdi"]]] },
  { id: "k03", baslik: "Dedemin Saati", resim: "🕰️ 👴 ❤️", ders: "Büyüklerimizin hatıraları değerlidir.",
    sayfalar: [
      "Dedemin cebinde eski, gümüş bir saat vardı. Saat tık tık diye çalışırdı.",
      "Dedem saati kurarken çok dikkatli olurdu. Küçük düğmeyi yavaş yavaş çevirir, sayardı: \"Bir, iki, üç... yirmi.\" Sonra saati kulağıma tutardı. Dedeme göre saati her akşam aynı saatte kurmak gerekirdi. \"Düzenli olan her şey uzun yaşar,\" derdi.",
      "Akşamları dedem saati kurar, sonra kulağıma tutardı. Tık tak, tık tak... Sanki saatin küçük bir kalbi vardı.",
      "Bir gün dedem saati bana gösterdi. \"Bunu bana babam vermişti.\" dedi.",
      "Dedem bana saatin hikâyesini anlattı. Büyük dedem bu saati yıllar önce bir pazardan almıştı. Saat savaş yıllarında, göçlerde, düğünlerde hep ailemizle birlikteydi. \"Bu saat ailemizin bütün güzel günlerine tanıklık etti,\" dedi.",
      "Saatin kapağında küçük bir kuş resmi vardı. Ona dikkatle dokundum.",
      "Saati açınca içindeki minik dişlileri gördüm. Hepsi birbirine bağlıydı. Biri dönünce öbürü de dönüyordu. Dedem, \"Bir aile de böyledir. Herkes birbirine destek olunca her şey yolunda gider,\" dedi. Bu sözü hiç unutmadım.",
      "Saat çok eskiydi ama hiç bozulmamıştı. Dedem, \"Eşyalarımıza iyi bakarsak uzun yıllar bizimle kalır.\" dedi.",
      "Bir gün saat durdu. Dedem onu bir saatçiye götürdü. Saatçi büyüteciyle içine baktı. \"Sadece biraz yağ istiyor,\" dedi. Saatçi minik dişlilere bir damla yağ sürdü. Saat yeniden tık tak etmeye başladı. Dedemle birlikte derin bir nefes aldık.",
      "Dedem gülümsedi: \"Büyüyünce bu saat senin olacak.\" Ben de onu çok iyi koruyacağıma söz verdim.",
      "O akşamdan sonra dedemle birlikte saati kurmak bizim küçük törenimiz oldu. Her akşam saat sekizde yan yana oturuyor, düğmeyi sırayla çeviriyorduk. Sonra dedem bana eski zamanlardan bir hikâye anlatıyordu. Tık tak sesi hikâyelere eşlik ediyordu."
    ],
    sorular: [["Saat nasıldı?","Eski ve gümüş",["Yeni ve plastik","Kırık"]],["Saatin kapağında ne resmi vardı?","Kuş",["Kedi","Gemi"]],["Çocuk dedesine ne söz verdi?","Saati iyi koruyacağına",["Saati satacağına","Saati kıracağına"]],["Dedeye saati kim vermişti?","Kendi babası",["Komşusu","Öğretmeni"]]] },
  { id: "k04", baslik: "Kayıp Top", resim: "⚽ 🌳 🐶", ders: "Yardımlaşınca sorunlar çözülür.",
    sayfalar: [
      "Mert ile Ali parkta top oynuyordu. Ali topa çok sert vurdu.",
      "Top, ağacın en yüksek dallarından birine sıkışmıştı. Ali ağacı salladı ama top kıpırdamadı. Mert yerden bir dal parçası alıp topa uzandı. Dal çok kısaydı. İkisi de ne yapacaklarını bilemeden ağacın altında oturdular.",
      "Mert'in gözleri doldu. Bu top ona doğum gününde hediye edilmişti. Üstünde bütün arkadaşlarının imzası vardı. \"Topumu orada bırakamam,\" dedi. Ağacın gövdesine bir ayağını koydu. Ali endişeyle arkadaşına baktı.",
      "Top uçtu ve yüksek bir ağacın dalına takıldı. Çocuklar üzüldü.",
      "Mert ağaca tırmanmak istedi. Ali hemen onu durdurdu: \"Yapma, düşebilirsin! Bir büyükten yardım isteyelim.\"",
      "Ali bekçi kulübesine koştu. Kapıyı nazikçe çaldı. \"Hasan Amca, topumuz ağaca takıldı. Bize yardım edebilir misiniz?\" dedi. Hasan Amca gözlüğünü düzeltti ve gülümsedi. \"Tabii ki evlat. Ama önce merdivenimi alalım,\" dedi.",
      "O sırada parkın bekçisi Hasan Amca geldi. Uzun merdivenini getirdi.",
      "Hasan Amca merdiveni ağaca dikkatle yasladı. Çocuklar merdivenin altını sıkıca tuttular.",
      "Hasan Amca merdivenden inerken çocuklara bir şey anlattı. \"Ben de küçükken böyle bir ağaca tırmanmıştım. Düştüm ve kolumu kırdım. Bir büyükten yardım istemekle çok akıllıca davrandınız,\" dedi. Mert ile Ali birbirine baktı.",
      "Hasan Amca topu indirdi. Çocuklar ona teşekkür etti ve bundan sonra topa yavaş vuracaklarını söylediler.",
      "O günden sonra Mert ile Ali parka her gidişlerinde Hasan Amca'ya selam verdiler. Bazen ona çay götürdüler, bazen de birlikte top oynadılar. Hasan Amca topa öyle güzel vuruyordu ki çocuklar şaşırıyordu. \"Gençliğimde iyi bir futbolcuydum,\" diyordu."
    ],
    sorular: [["Top nereye takıldı?","Ağacın dalına",["Çatıya","Çite"]],["Topu kim indirdi?","Hasan Amca",["Mert","Bir köpek"]],["Hasan Amca topu neyle indirdi?","Merdivenle",["İple","Sopayla"]],["Ali, Mert'i neden durdurdu?","Ağaçtan düşebilirdi",["Top yırtılmıştı","Hava kararmıştı"]]] },
  { id: "k05", baslik: "Ay'a Yolculuk", resim: "🚀 🌙 ⭐", ders: "Hayal kurmak ve merak etmek güzeldir.",
    sayfalar: [
      "Elif yatağına uzandı ve pencereden Ay'a baktı. \"Keşke oraya gidebilsem.\" dedi.",
      "Roketin içi ışıl ışıldı. Bir sürü düğme, ekran ve renkli ışık vardı. Elif bir astronot kıyafeti giymişti. Kaskının içinden kendi nefesini duyuyordu. Bir ses geri saymaya başladı: \"Beş, dört, üç, iki, bir... Kalkış!\"",
      "Gözlerini kapatınca kendini bir roketin içinde buldu. Roket yıldızların arasından geçti.",
      "Roketin penceresinden Dünya'ya baktı. Dünya mavi bir misket gibi parlıyordu. \"Ne kadar güzel!\" diye fısıldadı.",
      "Roket uzayda süzülürken Elif'in vücudu hafifledi. Kalemi elinden kaçtı ve havada asılı kaldı! Su damlaları küçük toplar gibi uçuşuyordu. Elif güldü ve havada takla attı. Uzayda yer çekimi neredeyse hiç yoktu.",
      "Ay'a indi. Yerde büyük çukurlar vardı. Elif tavşan gibi zıplayarak yürüdü.",
      "Ay'da hiç rüzgâr yoktu ve her yer sessizdi. Elif bir taşın üstüne Türk bayrağı çizdi ve kendi adını yazdı.",
      "Elif Ay'ın yüzeyinde ayak izleri bıraktı. Burada rüzgâr olmadığı için izler yıllarca silinmeyecekti. Gökyüzü simsiyahtı ama yıldızlar hiç olmadığı kadar parlaktı. Uzakta mavi Dünya bir fener gibi parlıyordu. Elif evini, ailesini özlediğini hissetti.",
      "Elif o gece yine pencereden Ay'a baktı. Bu sefer Ay'ın üstündeki gri lekeleri seçebiliyordu. Kitabında bu lekelerin büyük ovalar olduğunu okumuştu. \"Bir gün oraya gerçekten gideceğim,\" diye fısıldadı. Ay ona göz kırpar gibi parladı.",
      "Sabah annesinin sesiyle uyandı. Bu bir rüyaydı ama Elif büyüyünce astronot olmaya karar verdi.",
      "Elif kahvaltıda rüyasını ailesine anlattı. Babası ona uzay hakkında bir kitap aldı. Elif kitapta Ay'ın Dünya'dan çok uzak olduğunu, astronotların oraya günlerce yolculuk ettiğini öğrendi. Her gece yatmadan önce kitabından birkaç sayfa okudu."
    ],
    sorular: [["Elif nereye gitmek istiyordu?","Ay'a",["Denize","Ormana"]],["Elif Ay'da nasıl yürüdü?","Zıplayarak",["Koşarak","Sürünerek"]],["Elif büyüyünce ne olmak istiyor?","Astronot",["Aşçı","Pilot"]],["Dünya uzaydan neye benziyordu?","Mavi bir misket",["Sarı bir top","Kırmızı bir elma"]]] },
  { id: "k06", baslik: "Çalışkan Karınca", resim: "🐜 🍞 ☀️", ders: "Bugünün işini yarına bırakmayız.",
    sayfalar: [
      "Yaz boyunca karınca durmadan çalıştı. Buğday tanelerini yuvasına taşıdı.",
      "Karınca sabah güneş doğmadan yola çıkardı. Tarladaki buğday başaklarına tırmanır, taneleri tek tek koparırdı. Kendi ağırlığından çok daha ağır yükleri sırtında taşırdı. Yolda bir taş çıksa etrafından dolaşır, bir dal çıksa üstünden atlardı.",
      "Karıncaların yolu çok uzundu. Tarladan yuvaya giden yol boyunca dikenler, taşlar ve derin çatlaklar vardı. Ama karıncalar hep aynı yolu kullanır, birbirlerine kokularıyla işaret bırakırlardı. Böylece hiçbiri kaybolmazdı. Yol boyunca uzun, siyah bir çizgi oluşurdu.",
      "Ağustos böceği ise ağaç gölgesinde şarkı söylüyordu. \"Gel, biraz dinlen!\" diye seslendi.",
      "Karınca terlemişti ama yüzü gülüyordu. Arkadaşlarıyla tek sıra hâlinde yürüyor, herkes kendi yükünü taşıyordu.",
      "Bir gün yağmur yağdı ve yol çamur oldu. Karıncalar yine de çalışmaya devam etti. Biri düştüğünde öbürü yardım etti. Yükü ağır gelen karıncaya iki arkadaşı destek oldu. Ağustos böceği onları izlerken başını iki yana salladı.",
      "Karınca, \"Kış gelince yiyecek bulamayız.\" dedi ve çalışmaya devam etti.",
      "Sonbahar gelince yapraklar sarardı. Karıncanın yuvası buğdayla doldu. Ağustos böceği ise hâlâ şarkı söylüyordu.",
      "Kış gelmeden önce karınca yuvasını onardı. Kapısını kalın yapraklarla örttü. Buğdayları kuru odalara yerleştirdi. Yuvası artık sıcacık ve güvenliydi. Karınca dinlenmek için ilk kez yatağına uzandı ve rahatça uyudu.",
      "Kış gelince ağustos böceği acıktı. Karınca ona yiyeceğini paylaştı. Ağustos böceği gelecek yaz çalışacağını söyledi.",
      "Ağustos böceği ertesi yaz sözünü tuttu. Sabahları karıncalarla birlikte çalıştı, akşamları onlara şarkı söyledi. Karıncalar onun şarkılarıyla daha az yoruluyordu. Böylece hem çalışmanın hem de eğlenmenin birlikte güzel olduğunu öğrendiler."
    ],
    sorular: [["Karınca yazın ne yaptı?","Yiyecek taşıdı",["Uyudu","Şarkı söyledi"]],["Ağustos böceği yazın ne yaptı?","Şarkı söyledi",["Yuva yaptı","Buğday taşıdı"]],["Kışın karınca ne yaptı?","Yiyeceğini paylaştı",["Kapıyı kapattı","Uzaklara gitti"]],["Karıncalar yiyecekleri nasıl taşıdılar?","Tek sıra hâlinde",["Uçarak","Arabayla"]]] },
  { id: "k07", baslik: "Okulun İlk Günü", resim: "🎒 🏫 👧", ders: "Yeni ortamlarda cesur olmak bizi büyütür.",
    sayfalar: [
      "Ece'nin ailesi yeni bir şehre taşınmıştı. Bugün yeni okulunda ilk günüydü.",
      "Ece eski okulunu ve arkadaşlarını çok özlüyordu. Eski en iyi arkadaşı Beril ona bir mektup yazmıştı. Ece mektubu çantasının ön cebine koydu. \"Belki yeni okulda kimse benimle konuşmaz,\" diye düşündü. Annesi onun elini sıkıca tuttu.",
      "Sabah annesi saçlarını ördü. Ece yeni çantasına kalemlerini, defterlerini ve en sevdiği silgiyi koydu.",
      "Sınıfa girerken kalbi hızlı hızlı atıyordu. Kimseyi tanımıyordu.",
      "Öğretmen, \"Ece, bize kendini biraz tanıtır mısın?\" dedi. Ece ayağa kalktı. Sesi önce çok kısık çıktı. \"Benim adım Ece. Resim yapmayı ve kedileri çok severim,\" dedi. Sınıftan birkaç kişi, \"Ben de!\" diye bağırdı. Ece biraz rahatladı.",
      "Öğretmeni onu sınıfa tanıttı. Yanındaki sırada oturan Duru ona gülümsedi.",
      "Duru, \"Benim de ilk günüm çok heyecanlıydı. İstersen sana okulu gezdireyim.\" dedi. Kütüphaneyi ve resim atölyesini birlikte gezdiler.",
      "Öğle yemeğinde Duru, Ece'yi arkadaşlarının masasına çağırdı. Masada Kaan, Nil ve Ozan vardı. Herkes kendi beslenmesinden Ece'ye bir şey ikram etti. Nil'in annesi zeytinyağlı sarma koymuştu. Ece hayatında bu kadar lezzetli sarma yemediğini düşündü.",
      "Ertesi sabah Ece okula giderken hiç korkmuyordu. Kapıda Duru onu bekliyordu. İki arkadaş el ele sınıfa girdi. Öğretmenleri ikisine de gülümsedi. Ece yeni okulunun artık kendi okulu olduğunu hissetti.",
      "Teneffüste Duru onu ip atlamaya çağırdı. Akşam Ece annesine, \"Yeni okulumu çok sevdim!\" dedi.",
      "O akşam Ece eski arkadaşı Beril'e bir mektup yazdı. \"Seni çok özlüyorum. Ama yeni okulumda da güzel arkadaşlarım oldu. Bir gün hepinizi tanıştırmak istiyorum,\" diye yazdı. Mektubun altına iki kız ve bir kedi çizdi."
    ],
    sorular: [["Ece neden yeni okula gitti?","Taşındıkları için",["Okulu kapandığı için","Tatil olduğu için"]],["Ece'ye kim gülümsedi?","Duru",["Müdür","Annesi"]],["Teneffüste ne oynadılar?","İp atlama",["Saklambaç","Futbol"]],["Duru, Ece'ye nereleri gezdirdi?","Kütüphaneyi ve resim atölyesini",["Mutfağı ve bahçeyi","Hastaneyi"]]] },
  { id: "k08", baslik: "Su Damlası Pıtır", resim: "💧 ☁️ 🌈", ders: "Su çok değerlidir, israf etmeyiz.",
    sayfalar: [
      "Pıtır minik bir su damlasıydı. Denizde arkadaşlarıyla oynardı.",
      "Pıtır'ın denizde çok arkadaşı vardı. Dalgalarla birlikte kıyıya koşar, kumlara çarpıp geri dönerlerdi. Balıkların pullarında parlar, yengeçlerin kabuklarında dinlenirlerdi. Pıtır bazen merak ederdi: \"Denizin dışında ne var acaba?\"",
      "Bir gün sıcak bir güneş denizi ısıttı. Pıtır kendini bir tüy kadar hafif hissetti.",
      "Güneş ısıtınca Pıtır hafifledi ve gökyüzüne yükseldi. Bir bulutun içine girdi.",
      "Bulut rüzgârla birlikte denizin üstünden dağlara doğru yol aldı. Pıtır yukarıdan köyleri, tarlaları ve ormanları gördü. Aşağıda insanlar gökyüzüne bakıyor, yağmur bekliyorlardı. Çünkü uzun zamandır yağmur yağmamıştı. Tarlalar kupkuru olmuştu.",
      "Pıtır'ın bulutu bir dağın tepesine takıldı. Hava soğuktu. Pıtır'ın arkadaşlarından bazıları kar tanesine dönüştü ve dağın üstüne yağdı. Pıtır ise biraz daha aşağıda, köyün üstünde yağmur oldu. \"Kar da yağmur da sudan olur,\" diye düşündü.",
      "Bulut ağırlaşınca Pıtır yağmur olarak bir köye yağdı. Susamış bir çiçeğin köküne aktı.",
      "Bulutta binlerce damla arkadaşı vardı. Hepsi birbirine sarıldı ve bulut kocaman, gri bir pamuğa döndü.",
      "Yağmur yağınca köylüler sevinçle sokağa çıktı. Çocuklar yağmurun altında koşup oynadı. Kuruyan tarlalar ıslandı, dereler yeniden aktı. Bir çiftçi ellerini göğe açtı ve gülümsedi. \"Şükürler olsun, bereket geldi!\" dedi.",
      "Çiçek, \"Teşekkür ederim Pıtır!\" dedi. Pıtır suyun her damlasının çok değerli olduğunu anladı.",
      "Pıtır çiçeğin köklerinden yaprağına, yaprağından havaya çıktı. Yeniden bir buluta katıldı. Yolculuğu sona ermemişti, hiç ermeyecekti. Çünkü su, denizden buluta, buluttan toprağa, topraktan denize dönüp dolaşır. Buna su döngüsü denir."
    ],
    sorular: [["Pıtır neydi?","Su damlası",["Kar tanesi","Yaprak"]],["Pıtır gökyüzünde nereye girdi?","Buluta",["Kuş yuvasına","Uçağa"]],["Pıtır sonunda kime yardım etti?","Bir çiçeğe",["Bir balığa","Bir arabaya"]],["Pıtır'ı hafifleten neydi?","Güneşin sıcaklığı",["Rüzgârın soğuğu","Bir balık"]]] },
  { id: "k09", baslik: "Bayram Sabahı", resim: "🍬 👵 🎁", ders: "Bayramlar sevgiyi ve paylaşmayı artırır.",
    sayfalar: [
      "Bayram sabahı Yusuf erkenden uyandı. Yeni kıyafetlerini giydi.",
      "Yusuf aynanın karşısında yeni gömleğinin düğmelerini ilikledi. Babası onun saçlarını taradı. Küçük kız kardeşi Zehra da kırmızı elbisesini giymişti. Herkes çok şık olmuştu. Babası, \"Bayramda en güzel kıyafetlerimizi giyeriz,\" dedi.",
      "Mutfaktan mis gibi baklava kokusu geliyordu. Annesi bütün gece tatlı hazırlamıştı.",
      "Ailesiyle birlikte babaannesini ziyarete gittiler. Babaannesi kapıda onları sevinçle karşıladı.",
      "Babaannesinin evi bayram için hazırlanmıştı. Masalarda dantel örtüler, vazolarda taze çiçekler vardı. Sehpanın üstünde bir kâse lokum ve kolonya şişesi duruyordu. Babaannesi herkesin eline kolonya döktü. Yusuf'un burnuna limon kokusu geldi.",
      "Yusuf babaannesinin elini öptü. Babaannesi ona şeker ve küçük bir hediye verdi.",
      "Kuzenleri de gelmişti. Hep birlikte sofraya oturdular, sohbet ettiler. Babaannesi eski bayramları anlattı.",
      "Öğleden sonra Yusuf ile kuzenleri mahallede kapı kapı dolaştılar. Komşulara \"İyi bayramlar!\" dediler. Komşular onlara şeker ve çikolata verdi. Yusuf şekerlerini bir torbaya koydu. \"Bunları kardeşimle paylaşacağım,\" dedi.",
      "Gece yatarken Yusuf annesine sarıldı. \"Bayramlar neden bu kadar güzel?\" diye sordu. Annesi, \"Çünkü bayramda küsler barışır, büyükler ziyaret edilir, herkes birbirini sevindirir,\" dedi. Yusuf gözlerini kapattı ve gülümseyerek uyudu.",
      "Akşam Yusuf, komşuları yaşlı Ahmet Amca'ya da tatlı götürdü. Ahmet Amca çok mutlu oldu.",
      "Ahmet Amca yalnız yaşıyordu. Çocukları başka şehirdeydi. Yusuf'u kapıda görünce gözleri doldu. \"Beni hatırladığın için çok teşekkür ederim evladım,\" dedi. Yusuf, Ahmet Amca'nın elini öptü. Bayramın en güzel anının bu olduğunu düşündü. Ertesi sabah uyandığında ilk işi, şekerlerini kız kardeşi Zehra ile paylaşmak oldu."
    ],
    sorular: [["Yusuf bayram sabahı ne giydi?","Yeni kıyafetlerini",["Pijamasını","Montunu"]],["Önce kimi ziyaret ettiler?","Babaannesini",["Öğretmenini","Doktoru"]],["Akşam Yusuf kime tatlı götürdü?","Ahmet Amca'ya",["Kardeşine","Arkadaşına"]],["Mutfaktan ne kokusu geliyordu?","Baklava",["Çorba","Ekmek"]]] },
  { id: "k10", baslik: "Tembel Robot", resim: "🤖 🔋 🧹", ders: "Görevlerimizi zamanında yapmalıyız.",
    sayfalar: [
      "Kaan'ın oyuncak bir robotu vardı. Adı Bip'ti. Bip odayı toplamayı çok iyi bilirdi.",
      "Bip her sabah Kaan'ı \"Günaydın!\" diyerek uyandırırdı. Sonra kitapları rafa dizer, oyuncakları sepete koyar, çorapları çekmeceye yerleştirirdi. Kaan'ın odası hep tertemiz olurdu. Arkadaşları Kaan'a çok imrenirdi.",
      "Ama bir gün Bip, \"Bugün çok yorgunum, yarın toplarım.\" dedi.",
      "Kaan şaşırdı. Robotun ışıkları sönük sönük yanıyordu. Bip, oyuncakları yerde bırakıp köşede oturdu.",
      "Bir sonraki gün Bip yine, \"Yarın toplarım,\" dedi. Oda gittikçe dağıldı. Kaan ödevini yapmak istedi ama defterini bulamadı. Boya kalemleri halının altına kaçmıştı. Kaan, \"Böyle olmaz, Bip!\" diye söylendi.",
      "Ertesi gün oda daha da dağınıktı. Kaan legolara basıp \"Ay!\" diye bağırdı.",
      "Kaan, \"Bip, işleri biriktirirsek daha da zorlaşır.\" dedi. Bip'in ışıkları utançla kızardı.",
      "Kaan, Bip'e bir plan önerdi. \"Her akşam on dakika birlikte toplayalım. Böylece hiçbir şey birikmez.\" Bip bu fikri çok beğendi. Kaan kitapları, Bip oyuncakları topladı. On dakikada oda pırıl pırıl oldu.",
      "Bir gün Kaan'ın arkadaşları eve geldi. Odanın ne kadar düzenli olduğunu görünce şaşırdılar. \"Bunu nasıl yapıyorsun?\" diye sordular. Kaan ile Bip onlara on dakika planını anlattı. Arkadaşları da kendi evlerinde denemeye karar verdi.",
      "Bip özür diledi ve hemen odayı topladı. Sonra Kaan ile Bip, işleri birlikte yapmaya karar verdiler.",
      "O günden sonra Kaan ile Bip her akşam \"toplama şarkısı\" söyleyerek odayı topladılar. Kaan'ın annesi de çok sevindi. \"Demek ki iş paylaşınca kolaylaşıyormuş,\" dedi. Bip'in ışıkları mutluluktan rengârenk yandı. Kaan da Bip'e sarıldı ve onun en iyi arkadaşı olduğunu söyledi."
    ],
    sorular: [["Robotun adı neydi?","Bip",["Bop","Tık"]],["Bip odayı neden toplamadı?","Yorgun olduğunu söyledi",["Pili bitmişti","Kaan izin vermedi"]],["Kaan neye bastı?","Legolara",["Kediye","Kitaba"]],["Kaan, Bip'e ne söyledi?","İşleri biriktirmenin zor olduğunu",["Odayı hiç toplamamasını","Uyumasını"]]] },
  { id: "k11", baslik: "Köydeki Tatil", resim: "🐄 🌾 🐓", ders: "Doğa ve hayvanlar bize çok şey öğretir.",
    sayfalar: [
      "Yaz tatilinde Defne dedesinin köyüne gitti. Köyde horozun sesiyle uyandı.",
      "Dedesinin evi taştan yapılmıştı. Bahçesinde bir dut ağacı, bir de kuyu vardı. Defne sabah kahvaltısında köy peyniri, taze ekmek ve bal yedi. Ninesi, \"Bunların hepsi bizim köyümüzün,\" dedi. Defne her şeyi daha da lezzetli buldu.",
      "Dedesiyle ahıra gitti. İneği nasıl beslediklerini izledi.",
      "İnek Sarıkız sakin sakin ot yiyordu. Dedesi, \"Hayvanlara iyi bakarsak onlar da bize süt verir.\" dedi.",
      "Dedesi Defne'ye bir kova verdi. Birlikte ineği sağdılar. Süt, kovaya şırıl şırıl akıyordu. Defne ilk kez taze süt içti. Biraz sıcaktı ama çok güzeldi. Dedesi, \"Sabah sabah bu sütü içen çocuk kocaman olur,\" dedi.",
      "Ninesi ona tavukların yumurtalarını toplamayı gösterdi. Defne üç yumurta buldu.",
      "Öğleden sonra dere kenarına gittiler. Defne ayaklarını serin suya soktu ve küçük balıkları izledi.",
      "Dere kenarında köyün çocuklarıyla tanıştı. Ayşe ve Murat ona taş sektirmeyi öğretti. Defne'nin taşı önce suya batıyordu. Sonra bir kere, iki kere sekti. Çocuklar alkışladı. Akşama kadar oynadılar.",
      "Şehre dönünce Defne köyü çok özledi. Sabahları horoz sesi yerine araba seslerini duyuyordu. Ninesinin reçelini kahvaltıda yerken gözlerini kapattı. Sanki yine dut ağacının altındaydı. Defne bir sonraki yazı iple çekmeye başladı.",
      "Akşam yumurtalarla omlet yaptılar. Defne, \"Bu dünyanın en lezzetli omleti!\" dedi.",
      "Tatil bitince Defne'nin gözleri doldu. Ninesi ona bir kavanoz reçel, dedesi de bir sepet elma verdi. Ayşe ile Murat el salladı. Defne, \"Gelecek yaz yine geleceğim!\" diye bağırdı. Arabanın camından köyü son kez seyretti."
    ],
    sorular: [["Defne köyde neyin sesiyle uyandı?","Horozun",["Saatin","Kedinin"]],["Defne kaç yumurta buldu?","Üç",["Beş","Bir"]],["Akşam yumurtalarla ne yaptılar?","Omlet",["Pasta","Çorba"]],["İneğin adı neydi?","Sarıkız",["Pamuk","Benekli"]]] },
  { id: "k12", baslik: "Sihirli Sözcükler", resim: "🙏 ✨ 😊", ders: "Kibar sözcükler kalpleri açar.",
    sayfalar: [
      "Kerem bir şey isteyince hep \"Ver!\" derdi. Arkadaşları ona kırılırdı.",
      "Bir gün Kerem, Ayşe'nin kırmızı kalemini istedi. \"Ver şunu!\" dedi ve kalemi elinden çekti. Ayşe ağladı. Kerem şaşırdı. \"Ne oldu ki?\" dedi. Öğretmeni onu yanına çağırdı ve sakin bir sesle konuştu.",
      "Öğretmen Kerem'e, \"Ayşe'nin kalemini nasıl istedin?\" diye sordu. Kerem omuz silkti. \"Ver dedim.\" Öğretmen, \"Peki biri senden bir şeyi böyle isteseydi ne hissederdin?\" dedi. Kerem bir süre düşündü. \"Herhâlde üzülürdüm,\" dedi.",
      "Öğretmeni ona üç sihirli sözcük öğretti: lütfen, teşekkür ederim, özür dilerim.",
      "Kerem önce gülümsedi. \"Sözcükler nasıl sihirli olabilir?\" diye düşündü. Ama denemeye karar verdi.",
      "Öğretmen Kerem'e bir kartın üstüne üç sözcüğü yazdı. \"Bu kartı cebinde taşı. Bu sözcükleri kullandığında ne olduğunu gözle,\" dedi. Kerem kartı cebine koydu. İçinden, \"Bakalım gerçekten işe yarayacak mı?\" diye düşündü.",
      "Ertesi gün Kerem, \"Boyanı kullanabilir miyim, lütfen?\" dedi. Arkadaşı hemen boyasını uzattı.",
      "Teneffüste yanlışlıkla Deniz'in kalemini düşürdü. Hemen, \"Özür dilerim!\" dedi. Deniz, \"Önemli değil.\" diye gülümsedi.",
      "Akşam evde de sözcükleri denedi. Annesi yemeği koyunca, \"Teşekkür ederim anneciğim,\" dedi. Annesi şaşkınlıkla gülümsedi ve onu öptü. Kardeşinin oyuncağını alırken, \"Biraz oynayabilir miyim, lütfen?\" dedi. Kardeşi hemen oyuncağı verdi.",
      "Kerem, \"Teşekkür ederim!\" dedi. Sihirli sözcüklerin gerçekten işe yaradığını gördü.",
      "Bir hafta sonra Kerem'in sınıfta çok arkadaşı olmuştu. Ayşe ondan kalem istediğinde Kerem hemen verdi. Öğretmen, \"Sözcükler sihirli değil Kerem. Onları sihirli yapan, söyleyen kişinin kalbindeki saygı,\" dedi. Kerem bu sözü defterine yazdı."
    ],
    sorular: [["Kerem önce nasıl konuşurdu?","\"Ver!\" derdi",["Hep \"lütfen\" derdi","Hiç konuşmazdı"]],["Sihirli sözcükleri kim öğretti?","Öğretmeni",["Annesi","Dedesi"]],["Kerem arkadaşından ne istedi?","Boyasını",["Topunu","Kitabını"]],["Kerem kimin kalemini düşürdü?","Deniz'in",["Öğretmenin","Kendi"]]] },
  { id: "k13", baslik: "Cesur Kirpi", resim: "🦔 🍂 🦊", ders: "Herkesin kendine özgü güçleri vardır.",
    sayfalar: [
      "Ormanda Dikenli adında küçük bir kirpi yaşardı. Diğer hayvanlar onun dikenlerinden kaçardı.",
      "Dikenli bazen oyunlara katılmak isterdi. Ama tavşanlar, sincaplar ve kuşlar, \"Dikenlerin bize batar,\" diyerek uzaklaşırdı. Dikenli yalnız başına yaprak toplar, yalnız başına oynardı. Akşamları yuvasına dönünce ağlardı.",
      "Dikenli çok üzülürdü. \"Keşke yumuşak tüylerim olsaydı.\" derdi.",
      "Dikenli bir gün dere kenarında yalnız başına oturuyordu. Suya baktı ve kendi yansımasını gördü. Gözleri doldu.",
      "Annesi Dikenli'nin yanına geldi. \"Dikenlerin seni korumak için var,\" dedi. \"Bir gün ne kadar değerli olduklarını anlayacaksın.\" Dikenli annesinin sözlerini dinledi ama yine de biraz üzgündü. Annesi ona sarıldı.",
      "Bir gün aç bir tilki tavşanları kovaladı. Dikenli hemen önlerine geçip top gibi yuvarlandı.",
      "Tilki dikenlere çarpınca kaçtı. Tavşanlar Dikenli'ye sarıldı. Dikenli dikenlerinin ne kadar değerli olduğunu anladı.",
      "Tavşanlar Dikenli'ye teşekkür etti. Küçük tavşan, \"Sen bizim kahramanımızsın!\" dedi. Sincap ona en güzel fındıklarından getirdi. Kuşlar ağaçların tepesinden onun için şarkı söyledi. Dikenli ilk kez bu kadar mutlu oldu.",
      "Bir gün Dikenli'nin annesi ona sarıldı. \"Gördün mü? Seni farklı yapan şey, seni değerli de yapar,\" dedi. Dikenli başını salladı. Artık dikenleriyle gurur duyuyordu. O gece yıldızlara bakarak huzurla uyudu.",
      "O günden sonra ormandaki herkes Dikenli'yi oyunlarına çağırdı. Dikenli artık hiç yalnız değildi.",
      "Hayvanlar Dikenli'yle oynamanın bir yolunu buldular. Dikenleri batmasın diye yaprak toplarıyla oynuyorlardı. Dikenli de oyunlarda hep kaleci oluyordu. Hiçbir top onun dikenli kalesinden geçemiyordu! Ormanda en sevilen oyun bu oldu. Rüyasında bütün orman hayvanlarıyla birlikte top oynuyordu."
    ],
    sorular: [["Kirpinin adı neydi?","Dikenli",["Pamuk","Sincap"]],["Tilki kimleri kovalıyordu?","Tavşanları",["Kuşları","Balıkları"]],["Kirpi tavşanları nasıl korudu?","Top gibi yuvarlanarak",["Bağırarak","Ağaca çıkarak"]],["Hikâyenin sonunda Dikenli nasıl hissetti?","Mutlu ve değerli",["Yalnız ve üzgün","Kızgın"]]] },
  { id: "k14", baslik: "Kütüphanede Bir Gün", resim: "📚 🤫 🐉", ders: "Kitaplar bizi yeni dünyalara götürür.",
    sayfalar: [
      "Cumartesi günü Ömer annesiyle kütüphaneye gitti. İçerisi çok sessizdi.",
      "Kütüphanenin rafları tavana kadar uzanıyordu. Her rafta yüzlerce kitap vardı. Bir köşede minderler ve küçük masalar duruyordu. Çocuklar orada oturmuş kitap okuyordu. Ömer'in gözleri parladı. \"Burası bir hazine sandığı gibi!\" dedi.",
      "Kütüphaneci Nur Hanım onlara yardım etti. \"Hangi konuyu seversin?\" diye sordu. Ömer, \"Ejderhaları!\" dedi.",
      "Rafların arasında ejderhalarla ilgili renkli bir kitap buldu.",
      "Nur Hanım kütüphanenin kurallarını anlattı. \"Burada sessiz konuşuruz. Kitapların sayfalarını yırtmayız. Okuduktan sonra kitabı yerine koyarız,\" dedi. Ömer başını salladı. Kitabı tutarken sayfaları çok dikkatli çevirdi.",
      "Kitabı okurken kendini ejderhanın sırtında uçarken hayal etti. Saatin nasıl geçtiğini anlamadı.",
      "Kitapta ejderha ateş püskürmek yerine çiçek açtırıyordu. Ömer bu fikre çok güldü.",
      "Ömer kitabı bitirince kendi ejderha hikâyesini yazmaya karar verdi. Annesi ona bir defter aldı. Ömer'in ejderhası yağmur yağdırıyordu. Kuraklık olan köylere uçup tarlaları suluyordu. Ömer hikâyesinin her sayfasına bir resim çizdi.",
      "Ömer'in kütüphane kartı kısa sürede bir sürü damgayla doldu. Uzay, hayvanlar, denizaltılar... Her hafta yeni bir kitap okudu. Nur Hanım ona \"Ayın Okuru\" rozeti verdi. Ömer rozeti çantasına taktı ve herkese gururla gösterdi.",
      "Kütüphane kartı çıkardılar ve kitabı eve götürdüler. Ömer her hafta kütüphaneye gelmeye karar verdi.",
      "Bir sonraki hafta Ömer defterini Nur Hanım'a gösterdi. Nur Hanım çok beğendi. Hikâyeyi kütüphanenin çocuk panosuna astı. Ömer'in adı ve ejderhası panoda parlıyordu. \"Belki bir gün ben de bir kitap yazarım,\" diye düşündü. Annesi de onunla gurur duydu ve eve dönerken ona bir dondurma ısmarladı."
    ],
    sorular: [["Ömer kütüphaneye hangi gün gitti?","Cumartesi",["Pazartesi","Çarşamba"]],["Ömer nasıl bir kitap buldu?","Ejderhalarla ilgili",["Yemek kitabı","Matematik kitabı"]],["Ömer neye karar verdi?","Her hafta kütüphaneye gelmeye",["Hiç kitap okumamaya","Kitabı saklamaya"]],["Kitaptaki ejderha ne yapıyordu?","Çiçek açtırıyordu",["Ateş püskürüyordu","Uyuyordu"]]] },
  { id: "k15", baslik: "Deprem Tatbikatı", resim: "🔔 🐢 🏫", ders: "Hazırlıklı olmak bizi korur.",
    sayfalar: [
      "Okulda zil farklı bir sesle çaldı. Öğretmen, \"Çocuklar, tatbikat yapıyoruz!\" dedi.",
      "Zil sesi kısa kısa ve hızlı çalıyordu. Bazı çocuklar ne olduğunu anlamadı. Öğretmen hemen sakin bir sesle konuştu: \"Çök, kapan, tutun!\" Herkes ne yapacağını bildiği için kimse panik yapmadı.",
      "Herkes sıranın yanına çöktü, başını kollarıyla kapattı ve sıranın ayağına tutundu.",
      "Bazı çocuklar biraz korkmuştu. Öğretmen sakin bir sesle, \"Korkmayın, ne yapacağımızı öğreniyoruz.\" dedi.",
      "Bahçede herkes sınıf sınıf sıraya girdi. Öğretmen her öğrencinin adını okudu. \"Burada!\" diye cevap verdiler. Müdür Bey bir düdük çaldı. \"Tebrik ederim, okulu üç dakikada güvenle boşalttık,\" dedi.",
      "Sonra sırayla, koşmadan ve itişmeden bahçedeki toplanma alanına gittiler.",
      "Öğretmen, \"Çok iyiydiniz! Çök, kapan, tutun kuralını unutmayın.\" dedi. Çocuklar kendilerini güvende hissetti.",
      "Öğretmen deprem sırasında nelere dikkat etmemiz gerektiğini anlattı. \"Merdivenlerde koşmayız. Asansöre binmeyiz. Pencerelerden ve camlardan uzak dururuz. Dışarıdaysak ağaçlardan ve elektrik direklerinden uzaklaşırız,\" dedi. Çocuklar dikkatle dinledi.",
      "Bir ay sonra okulda yangın tatbikatı da yapıldı. Çocuklar bu sefer hiç korkmadı. Ne yapacaklarını biliyorlardı. Öğretmenleri onlarla gurur duydu. \"Hazırlıklı olmak, korkuyu yener,\" dedi.",
      "Akşam Ali, evde de ailesiyle bir deprem çantası hazırladı. İçine su, el feneri ve düdük koydular.",
      "Ali'nin ailesi deprem çantasına ilk yardım malzemeleri, piller, kuru yiyecekler ve battaniye de ekledi. Aile toplanma alanını birlikte belirledi. Ali kardeşine de \"Çök, kapan, tutun\" hareketini öğretti. Hazırlıklı olmak herkesi rahatlatmıştı. Ali de o akşam ailesine okulda öğrendiklerini tek tek anlattı. Babası onu dikkatle dinledi ve not aldı."
    ],
    sorular: [["Okulda ne yapıldı?","Deprem tatbikatı",["Doğum günü","Spor yarışı"]],["Çocuklar nereye gittiler?","Toplanma alanına",["Kantine","Eve"]],["Depremde hangi kurala uyarız?","Çök, kapan, tutun",["Koş, bağır, it","Asansöre bin"]],["Ali deprem çantasına ne koydu?","Su, el feneri ve düdük",["Oyuncak ve şeker","Hiçbir şey"]]] },
  { id: "k16", baslik: "Kuşların Yuvası", resim: "🐦 🥚 🌸", ders: "Hayvanlara şefkat göstermeliyiz.",
    sayfalar: [
      "İlkbaharda Selin'in penceresinin önüne iki serçe yuva yaptı.",
      "Selin önce serçeleri kovalamak istedi. Pencere pervazını kirletiyorlardı. Ama annesi, \"Onlar yavruları için yuva yapıyor. Biraz sabredelim,\" dedi. Selin pencerenin önüne bir sandalye çekti ve kuşları sessizce izlemeye başladı.",
      "Serçeler ağızlarında küçük çöpler ve tüyler taşıyordu. Yuvayı büyük bir sabırla örüyorlardı.",
      "Bir süre sonra yuvada üç küçük yumurta belirdi. Selin her gün onları uzaktan izledi.",
      "Selin bir defter tuttu. Her gün yuvada ne gördüğünü yazdı. \"Birinci gün: Anne serçe yumurtaların üstünde oturuyor. Üçüncü gün: Baba serçe ona yiyecek getirdi.\" Defter, kuşların hikâyesiyle dolmaya başladı.",
      "Yumurtalardan minik yavrular çıktı. Ağızlarını açıp cik cik diye bağırıyorlardı.",
      "Anne ve baba serçe sırayla yavrulara böcek getiriyordu. Selin onları korkutmamak için pencereyi açmıyordu.",
      "Yavrular her gün büyüdü. Tüyleri çıktı, kanatları güçlendi. Bir sabah en büyük yavru yuvanın kenarına çıktı. Kanatlarını çırptı ve ilk kez uçtu! Selin heyecandan nefesini tuttu. Ötekiler de birer birer onu izledi.",
      "Ertesi ilkbahar serçeler yine geldi. Bu sefer eski yuvayı onardılar. Selin yeni defterini açtı ve ilk sayfaya şöyle yazdı: \"Serçeler geri döndü!\" Pencerenin önündeki su kabını tazeledi ve onları izlemeye başladı.",
      "Selin pencereye bir kap su koydu. Yavrular büyüyüp uçunca Selin onlara el salladı.",
      "Yuva boş kaldı ama Selin üzülmedi. Çünkü serçeler hâlâ her sabah pencerenin önüne gelip suyundan içiyordu. Selin defterini öğretmenine gösterdi. Öğretmeni ona bir yıldız verdi ve defteri sınıfta herkese okuttu. Bu kez yavruların uçuşunu da fotoğrafla kaydetmeye karar verdi."
    ],
    sorular: [["Kuşlar yuvayı nereye yaptı?","Pencerenin önüne",["Çatıya","Bahçeye"]],["Yuvada kaç yumurta vardı?","Üç",["İki","Beş"]],["Selin pencereye ne koydu?","Bir kap su",["Bir oyuncak","Bir kitap"]],["Selin pencereyi neden açmıyordu?","Kuşları korkutmamak için",["Hava soğuk olduğu için","Kırık olduğu için"]]] },
  { id: "k17", baslik: "Halı Saha Maçı", resim: "⚽ 🥅 🤝", ders: "Kazanmak kadar güzel oynamak da önemlidir.",
    sayfalar: [
      "Emir'in takımı mahalle maçına çıktı. Herkes çok heyecanlıydı.",
      "Takımda Emir, Berk, Mete, Arda ve Kuzey vardı. Haftalardır antrenman yapıyorlardı. Her sabah parkta koşuyor, pas çalışıyorlardı. Emir'in babası onlara forma almıştı. Formaların üstünde takımın adı yazıyordu: Yıldızlar.",
      "Maçtan önce takımca el ele tutuştular. Kaptan Emir, \"Kazansak da kaybetsek de güzel oynayalım!\" dedi.",
      "Maçın sonunda rakip takım bir gol attı. Emir'in takımı maçı kaybetti.",
      "Devre arasında takım bir araya geldi. Arda, \"Hiç gol atamıyoruz,\" diye üzüldü. Emir, \"Daha çok pas verelim. Kimse tek başına oynamasın,\" dedi. İkinci yarıda takım daha iyi oynadı. Ama şanssız bir şut direkten döndü.",
      "Emir'in takımı da çok uğraştı. Kaleci Berk iki önemli kurtarış yaptı. Ama top bir türlü gole gitmedi.",
      "Emir önce üzüldü. Sonra rakip takımın kaptanının elini sıktı ve onu tebrik etti.",
      "Maçtan sonra iki takım birlikte meyve suyu içti. Rakip takımın kalecisi Berk'e, \"Kurtarışların harikaydı,\" dedi. Çocuklar hangi futbolcuyu sevdiklerini konuştular. Kimi Galatasaray'ı, kimi başka takımları tutuyordu ama hepsi futbolu çok seviyordu.",
      "Akşam Emir babasına maçı anlattı. Babası, \"Kaybetmek de oyunun bir parçası. Önemli olan ondan ne öğrendiğin,\" dedi. Emir, \"Pas vermeyi ve rakibe saygıyı öğrendim,\" dedi. Babası onu kucakladı.",
      "Rakip kaptan, \"Çok iyi oynadınız, haftaya yine oynayalım!\" dedi. İki takım arkadaş oldu.",
      "Bir hafta sonra rövanş maçı oynandı. Bu sefer Emir'in takımı bir gol attı, maç berabere bitti. İki takım sahanın ortasında el ele tutuşup selam verdi. Maçı izleyen aileler hepsini alkışladı. Emir, \"Asıl kazanan dostluk oldu,\" dedi."
    ],
    sorular: [["Maç nerede oynandı?","Mahallede",["Okulda","Stadyumda"]],["Maçı kim kazandı?","Rakip takım",["Emir'in takımı","Kimse"]],["Emir maçtan sonra ne yaptı?","Rakibi tebrik etti",["Ağladı","Topu attı"]],["Maçtan önce Emir arkadaşlarına ne dedi?","Güzel oynayalım",["Ne olursa olsun kazanalım","Kavga edelim"]]] },
  { id: "k18", baslik: "Geri Dönüşüm Kahramanları", resim: "♻️ 🧴 🌍", ders: "Atıkları ayırarak doğayı koruruz.",
    sayfalar: [
      "Sınıfta öğretmen üç renkli kutu gösterdi: mavi kâğıtlar, sarı plastikler, yeşil camlar için.",
      "Öğretmen her kutunun ne için olduğunu tek tek gösterdi. Gazeteler, defter kâğıtları ve kartonlar mavi kutuya gidiyordu. Su şişeleri ve yoğurt kapları sarı kutuya, kavanozlar ve cam şişeler yeşil kutuya. Çocuklar renkleri hemen öğrendi.",
      "Öğretmen, \"Bir plastik şişe doğada yüzlerce yıl kaybolmaz. Ama geri dönüşürse yeni bir eşyaya dönüşebilir.\" dedi.",
      "Çocuklar bir hafta boyunca atıkları doğru kutuya attı.",
      "Bazen hatalar oldu. Kaan bir cam şişeyi sarı kutuya attı. Elif onu nazikçe uyardı: \"Kaan, cam yeşil kutuya gidiyor.\" Kaan şişeyi aldı ve doğru kutuya koydu. \"Teşekkürler Elif,\" dedi. Böylece birbirlerine öğrettiler.",
      "Hafta sonunda kutular doldu. Belediye görevlileri gelip onları geri dönüşüme götürdü.",
      "Toplanan plastiklerden okula renkli bir bank yapıldı. Çocuklar bankın üstüne oturup sevinçle fotoğraf çektirdi.",
      "Çocuklar okulda çöp toplama günü düzenledi. Eldivenlerini takıp bahçedeki kâğıtları, şişeleri topladılar. Toplananları ayırdılar. Okul bahçesi tertemiz oldu. Müdür Bey onlara teşekkür edip hepsine bir fidan hediye etti.",
      "Yıl sonunda okulda bir sergi yapıldı. Çocuklar atıklardan yaptıkları oyuncakları, saksıları ve kalemlikleri sergiledi. Veliler çok beğendi. Bir dede, \"Biz küçükken hiçbir şeyi atmazdık. Siz de bu güzel geleneği sürdürüyorsunuz,\" dedi.",
      "Öğretmen, \"Siz birer doğa kahramanısınız!\" dedi. Çocuklar evde de atıkları ayırmaya başladı.",
      "Melis evde annesiyle birlikte geri dönüşüm köşesi yaptı. Eski kutuları boyayıp üstüne resimler çizdiler. Plastik şişelerden saksılar yaptılar. Komşuları da bunu görünce kendi evlerinde atıklarını ayırmaya başladı. Küçük bir fikir bütün apartmana yayılmıştı."
    ],
    sorular: [["Kâğıtlar hangi renk kutuya atıldı?","Mavi",["Sarı","Yeşil"]],["Kutuları kim götürdü?","Belediye görevlileri",["Öğrenciler","Müdür"]],["Öğretmen çocuklara ne dedi?","Doğa kahramanı",["Tembel","Gürültücü"]],["Toplanan plastiklerden ne yapıldı?","Renkli bir bank",["Bir top","Bir kitap"]]] },
  { id: "k19", baslik: "Ressam Kız", resim: "🎨 🖌️ 🖼️", ders: "Yeteneklerimizi geliştirmek için çalışırız.",
    sayfalar: [
      "Ayşe resim yapmayı çok severdi. Ama çizdiği atlar hep köpeğe benzerdi.",
      "Ayşe'nin arkadaşları onun resimlerine bakıp gülüyordu. \"Bu at mı, köpek mi?\" diyorlardı. Ayşe kırılıyordu. Resim defterini kapatıp çekmecesine kaldırdı. \"Ben hiç iyi bir ressam olamayacağım,\" diye düşündü.",
      "Bir gün vazgeçmek istedi. Ablası, \"Her gün biraz çalışırsan gelişirsin.\" dedi.",
      "Ayşe, ablasıyla birlikte parka gidip gerçek atları ve köpekleri izledi. Atların bacaklarının ne kadar uzun olduğunu fark etti.",
      "Ayşe atları çizmeden önce onları dikkatle inceledi. Yelelerinin nasıl dalgalandığına, kulaklarının nasıl dik durduğuna baktı. Bacaklarının uzun ve ince olduğunu, kuyruklarının yere kadar uzandığını gördü. Gördüklerini defterine küçük notlar olarak yazdı.",
      "Ayşe her akşam bir at çizdi. Her resim bir öncekinden daha güzeldi.",
      "Bazen resmini beğenmedi ve kâğıdı buruşturdu. Ama ertesi gün yeniden denedi.",
      "Ablası ona ünlü ressamların da çok çalıştığını anlattı. \"Büyük ressamlar bir resmi bazen yüz kere çizermiş,\" dedi. Ayşe şaşırdı. \"Yüz kere mi?\" Ablası gülümsedi. \"Evet. Hata yapmak öğrenmenin bir parçası,\" dedi.",
      "Ayşe artık her hafta parka gidip resim yapıyordu. Ağaçları, kuşları, insanları çiziyordu. Defteri doldukça yenisini alıyordu. Bir gün küçük bir kız yanına geldi. \"Bana da öğretir misin?\" diye sordu. Ayşe gülümseyerek ona bir kalem uzattı.",
      "Okulda resim sergisi açıldı. Ayşe'nin at resmi panonun en ortasına asıldı.",
      "Sergide insanlar Ayşe'nin resminin önünde durdu. Bir öğretmen, \"Bu atın gözleri sanki konuşuyor,\" dedi. Ayşe'nin ablası onu kucakladı. Eskiden ona gülen arkadaşları da resmi alkışladı. Ayşe, pes etmediği için kendisiyle gurur duydu."
    ],
    sorular: [["Ayşe'nin atları neye benziyordu?","Köpeğe",["Kuşa","Balığa"]],["Ayşe'ye kim cesaret verdi?","Ablası",["Dedesi","Komşusu"]],["Ayşe'nin resmi nereye asıldı?","Panonun ortasına",["Kapının arkasına","Hiçbir yere"]],["Ayşe atları çizmeyi nasıl öğrendi?","Gerçek atları izleyip her gün çalışarak",["Hiç çalışmadan","Resimleri kopyalayarak"]]] },
  { id: "k20", baslik: "Yarım Elma", resim: "🍎 🍏 👫", ders: "Paylaşınca her şey daha güzel olur.",
    sayfalar: [
      "Teneffüste Arda'nın beslenme çantasında tek bir elma vardı. Sınıfa yeni gelen Bora'nın ise hiç yiyeceği yoktu.",
      "Arda, Bora'nın açlıktan karnının guruldadığını duydu. Bora bunu duyunca utandı ve başını eğdi. Arda onu daha önce hiç bu kadar sessiz görmemişti. Bora sınıfa yeni gelmişti ve henüz hiç arkadaşı yoktu.",
      "Arda elmasına baktı. Elma kocaman ve kıpkırmızıydı. Annesi onu sabah özenle yıkamış ve beslenme çantasına koymuştu. Arda'nın karnı da acıktı. Ama Bora'nın yüzündeki üzgün ifadeyi görünce içi sızladı.",
      "Bora sırasında sessizce oturuyordu. Arkadaşlarının yemek yemesini izliyor, kimseye bir şey söylemiyordu.",
      "Arda bir an düşündü. Sonra öğretmeninden elmayı ikiye bölmesini istedi.",
      "Öğretmen, Arda'nın ne yapmak istediğini anladı. Onu omzundan okşadı. \"Paylaşmak çok güzel bir davranış Arda,\" dedi. Elmayı dikkatlice ikiye böldü. İki yarım tam olarak eşitti. Öğretmen, \"İşte bunlar iki yarım, yani iki tane bir bölü iki,\" dedi.",
      "Öğretmen elmayı iki eş parçaya böldü. Arda yarımını Bora'ya uzattı.",
      "Bora gülümsedi. \"Yarım elma, bütün bir arkadaşlık!\" dedi. İki çocuk o günden sonra hiç ayrılmadı.",
      "Teneffüste Arda ile Bora birlikte bahçeye çıktı. Bora ona eski okulunu, köydeki evini ve köpeği Karabaş'ı anlattı. Arda da ona en sevdiği oyunları öğretti. Saklambaç oynadılar, sek sek çizdiler. Zil çaldığında ikisi de gülüyordu.",
      "Ertesi gün Bora'nın annesi iki kurabiye koymuştu. Bora birini Arda'ya verdi. \"Şimdi sıra bende!\" dedi.",
      "Ay sonunda sınıfta \"En iyi arkadaşını anlat\" diye bir etkinlik yapıldı. Arda, Bora'yı; Bora da Arda'yı anlattı. Bora, \"Arda yarım elmasını benimle paylaştı. Ama bana verdiği şey elmadan çok daha büyüktü,\" dedi. Bütün sınıf alkışladı."
    ],
    sorular: [["Arda'nın çantasında ne vardı?","Bir elma",["Bir sandviç","Bir muz"]],["Elmayı kim böldü?","Öğretmen",["Arda","Bora"]],["Elma kaç parçaya bölündü?","İki",["Dört","Üç"]],["Ertesi gün Bora, Arda'ya ne verdi?","Bir kurabiye",["Bir elma","Bir kalem"]]] },
  /* ───── Klasiklerden uyarlamalar ───── */
  {"id":"k21","baslik":"Keloğlan ile Dev","resim":"👦 👹 🧀","kaynak":"Türk halk masalından uyarlama","ders":"Zekâ, kaba kuvvetten güçlüdür.","sayfalar":["Evvel zaman içinde, kalbur saman içinde, Keloğlan adında bir delikanlı anasıyla birlikte küçük bir evde yaşarmış. Çok fakirlermiş ama Keloğlan'ın aklı da cesareti de yerindeymiş.","Bir gün anası, \"Oğul, evde un kalmadı. Git ormandan biraz odun topla, pazarda sat da un alalım,\" demiş. Keloğlan sırtına ipini, cebine de bir parça peynir koymuş ve yola düşmüş.","Ormanın derinliklerinde kocaman bir dev çıkmış karşısına. Devin boyu çınar ağacı kadarmış. Sesi gök gürültüsü gibi gürlüyormuş. \"Benim ormanımda ne arıyorsun? Seni bir lokmada yerim!\" diye bağırmış.","Keloğlan korkmuş ama hiç belli etmemiş. \"Beni yiyemezsin, ben senden güçlüyüm,\" demiş. Dev kahkahayla gülmüş. \"Öyleyse göster bakalım gücünü!\" demiş. Yerden bir taş alıp avucunda sıkmış, taş toz olmuş.","Keloğlan cebinden peyniri çıkarmış. Dev görmesin diye onu taş gibi tutmuş ve sıkmış. Peynirin suyu damla damla yere akmış. \"Sen taşı toz yaptın, ben ise taştan su çıkardım!\" demiş. Dev şaşkınlıktan ağzını açık bırakmış.","Dev bu sefer bir taşı havaya fırlatmış. Taş çok yükseğe çıkıp geri düşmüş. Keloğlan yerden bir serçe yakalamış, onu da taş gibi tutup havaya atmış. Serçe uçmuş gitmiş, bir daha geri gelmemiş. \"Benim taşım hiç düşmedi!\" demiş Keloğlan.","Dev artık iyice korkmuş. \"Bu kadar güçlü birine dokunmamak lazım,\" diye düşünmüş. Keloğlan'a bir kese altın vermiş. \"Al bunu ve beni rahat bırak,\" demiş. Sonra koşa koşa ormanın derinliklerine kaçmış.","Keloğlan altınlarla eve dönmüş. Anasıyla birlikte un almışlar, köyün fakirlerine de dağıtmışlar. Köylüler, \"Keloğlan devi nasıl yendin?\" diye sormuşlar. Keloğlan gülmüş: \"Kolumla değil, aklımla!\" Gökten üç elma düşmüş: biri bana, biri anlatana, biri de dinleyene."],"sorular":[["Keloğlan ormana ne için gitti?","Odun toplamaya",["Dev aramaya","Avlanmaya"]],["Keloğlan taş yerine neyi sıktı?","Peyniri",["Elmayı","Ekmeği"]],["Keloğlan havaya ne attı?","Bir serçe",["Bir taş","Bir top"]],["Keloğlan devi neyle yendi?","Aklıyla",["Kılıcıyla","Kollarıyla"]]]},
  {"id":"k22","baslik":"Bremen Mızıkacıları","resim":"🫏 🐕 🐈 🐓 🎶","kaynak":"Grimm Kardeşler masalından uyarlama","ders":"Birlik olanlar zorlukları aşar.","sayfalar":["Bir köyde yaşlı bir eşek vardı. Yıllarca un çuvalları taşımıştı. Artık yorulmuştu ve sahibi onu istemiyordu. Eşek, \"Bremen şehrine gidip sokak müzisyeni olacağım,\" dedi ve yola çıktı.","Yolda yorgun bir köpeğe rastladı. Köpek de yaşlanmıştı, ava gidemiyordu. \"Benimle gel. Ben ud çalarım, sen davul çalarsın,\" dedi eşek. Köpek sevindi ve onunla yürümeye başladı.","Biraz ilerde üzgün bir kedi gördüler. Dişleri körelmişti, fare yakalayamıyordu. \"Sen de bizimle gel, gece şarkılarını iyi bilirsin,\" dediler. Sonra bir çiftliğin çitinde öten bir horoz buldular. Horoz da onlara katıldı.","Akşam olunca ormanda dinlenmek istediler. Uzakta bir ışık gördüler. Işık, ormanın ortasındaki bir evden geliyordu. Eşek pencereden içeri baktı. Masada bir sürü yemek vardı ve etrafında haydutlar oturuyordu.","Hayvanlar bir plan yaptı. Köpek eşeğin sırtına, kedi köpeğin sırtına, horoz da kedinin başına çıktı. Sonra hep birlikte şarkı söylediler. Eşek anırdı, köpek havladı, kedi miyavladı, horoz öttü!","Bu korkunç ses pencereden içeri doldu. Haydutlar ne olduğunu anlamadı. \"Bir canavar geliyor!\" diye bağırdılar ve evden kaçıp ormana dağıldılar. Hayvanlar içeri girip karınlarını doyurdu.","Gece haydutlardan biri evi gözetlemek için geri geldi. Karanlıkta kedinin parlayan gözlerini kor ateş sandı. Kedi onu tırmaladı, köpek bacağını ısırdı, eşek bir tekme attı, horoz da \"Kukuriku!\" diye bağırdı.","Haydut arkadaşlarının yanına koştu. \"Evde bir cadı, bir canavar, bir dev var!\" dedi. Haydutlar bir daha o eve dönmedi. Dört arkadaş Bremen'e hiç gitmedi. Ormandaki evde birlikte mutlu mesut yaşadılar."],"sorular":[["Yolculuğa ilk kim çıktı?","Eşek",["Köpek","Horoz"]],["Hayvanlar nereye gitmek istiyordu?","Bremen şehrine",["Denize","Dağa"]],["Haydutları ne korkuttu?","Hayvanların hep birlikte çıkardığı ses",["Bir aslan","Yağmur"]],["Masal ne öğretir?","Birlik olanlar başarır",["Yalnız kalmak iyidir","Şarkı söylemek ayıptır"]]]},
  {"id":"k23","baslik":"Hansel ile Gretel","resim":"👦 👧 🍭 🏠","kaynak":"Grimm Kardeşler masalından uyarlama","ders":"Zor anlarda akıllı ve dayanışmalı olmalıyız.","sayfalar":["Ormanın kenarında oduncu bir baba ve iki çocuğu, Hansel ile Gretel yaşardı. Bir gün baba ve çocuklar odun toplamak için ormanın derinliklerine gittiler. Hansel yol boyunca cebindeki beyaz çakıl taşlarını tek tek yere bıraktı.","Akşama doğru baba odun keserken çocuklar oyuna daldı ve kayboldular. Gretel ağlamaya başladı. Hansel, \"Korkma, ay doğunca yolu bulacağız,\" dedi. Ay ışığında beyaz taşlar parladı ve onlar evin yolunu buldular.","Birkaç gün sonra yine ormana gittiler. Bu sefer Hansel'in cebinde taş yoktu. Yola ekmek kırıntıları bıraktı. Ama kuşlar kırıntıları yedi! Çocuklar yine kayboldular ve geri dönemediler.","Bütün gece yürüdüler. Sabah olunca ormanın içinde garip bir ev gördüler. Duvarları zencefilli kurabiyeden, çatısı pastadan, pencereleri şekerdendi! Çocuklar çok açtı ve evden parça koparıp yemeye başladılar.","Kapı açıldı ve yaşlı bir kadın çıktı. \"İçeri gelin çocuklar, size sıcak yemek vereyim,\" dedi. Ama bu kadın aslında kötü bir cadıydı. Çocukları içeri alınca Hansel'i bir kafese kilitledi, Gretel'e de ev işi yaptırdı.","Cadının gözleri iyi görmüyordu. Her gün Hansel'e, \"Parmağını uzat, şişmanlamış mısın bakayım,\" diyordu. Akıllı Hansel parmağı yerine ince bir kemik uzatıyordu. Cadı şaşırıyor, \"Bu çocuk hiç şişmanlamıyor!\" diye söyleniyordu.","Bir gün cadı fırını yaktı ve Gretel'e, \"Fırının içine bak, ateş iyi yanıyor mu?\" dedi. Gretel cadının planını anladı. \"Nasıl bakılacağını bilmiyorum, bana gösterir misin?\" dedi. Cadı eğilince Gretel onu itti ve fırının kapağını kapattı.","Gretel hemen Hansel'i kafesten çıkardı. Evde cadının sakladığı mücevherleri buldular. Ormanda yürürken bir gölün kenarında beyaz bir ördek onları sırtına alıp karşıya geçirdi. Sonunda evlerini buldular. Babaları onlara sarıldı ve bir daha hiç ayrılmadılar."],"sorular":[["Hansel ilk yolculukta yere ne bıraktı?","Beyaz çakıl taşları",["Ekmek","Çiçek"]],["Ekmek kırıntılarına ne oldu?","Kuşlar yedi",["Yağmur sildi","Rüzgâr uçurdu"]],["Ev neyden yapılmıştı?","Kurabiye ve şekerden",["Taştan","Tahtadan"]],["Hansel cadıyı nasıl kandırdı?","Parmağı yerine kemik uzatarak",["Kaçarak","Saklanarak"]]]},
  {"id":"k24","baslik":"Kurbağa Prens","resim":"👸 🐸 ⚽","kaynak":"Grimm Kardeşler masalından uyarlama","ders":"Verdiğimiz sözü tutarız.","sayfalar":["Bir zamanlar bir kralın çok güzel bir kızı vardı. Prenses en çok altın topuyla oynamayı severdi. Sarayın bahçesindeki derin kuyunun kenarında topunu havaya atar, tutar, yine atardı.","Bir gün top elinden kaydı ve kuyuya düştü. Prenses ağlamaya başladı. Kuyudan yeşil, kocaman gözlü bir kurbağa çıktı. \"Neden ağlıyorsun prenses?\" diye sordu. Prenses ona olanları anlattı.","Kurbağa, \"Topunu çıkarırsam bana ne verirsin?\" dedi. Prenses, \"Ne istersen! Elbiselerimi, incilerimi, tacımı!\" dedi. Kurbağa, \"Hiçbirini istemem. Sadece arkadaşın olmak, sofranda yemek yemek istiyorum,\" dedi. Prenses hemen söz verdi.","Kurbağa suya daldı ve altın topu ağzında getirdi. Prenses topu kaptı ve teşekkür bile etmeden saraya koştu. Kurbağa arkasından, \"Bekle beni!\" diye bağırdı. Ama prenses onu çoktan unutmuştu.","Akşam kral ve prenses yemek yerken kapı çalındı. \"Prenses, kapıyı aç! Sözünü hatırla!\" diye bir ses geldi. Prenses kapıyı açınca kurbağayı gördü ve kapıyı hemen kapattı. Kral ne olduğunu sordu.","Prenses olanları anlattı. Kral ciddi bir yüzle, \"Bir söz verdiysen tutmalısın. Sana yardım edeni küçümseme,\" dedi. Prenses istemeye istemeye kapıyı açtı. Kurbağa içeri girdi ve masaya, prensesin tabağının yanına oturdu.","Prenses ilk başta kurbağadan hoşlanmadı. Ama kurbağa ona sarayın dışındaki dünyayı, kuyunun altındaki gizli bahçeleri anlattı. Çok komik hikâyeleri vardı. Prenses yavaş yavaş gülmeye başladı. \"Sen çok iyi bir arkadaşsın,\" dedi.","Prenses bunu söyler söylemez kurbağa bir ışık içinde kayboldu. Yerinde genç bir prens duruyordu! Kötü bir büyücü onu kurbağaya çevirmişti. Büyü, birinin onu gerçekten arkadaş olarak kabul etmesiyle bozulacaktı. Prens ile prenses iyi birer dost oldular."],"sorular":[["Prensesin topu nereye düştü?","Kuyuya",["Denize","Ağaca"]],["Kurbağa ne istedi?","Prensesin arkadaşı olmak",["Altın","Bir taç"]],["Kral prensese ne dedi?","Sözünü tutmalısın",["Kurbağayı kov","Topunu at"]],["Kurbağa aslında kimdi?","Bir prens",["Bir büyücü","Bir kral"]]]},
  {"id":"k25","baslik":"İmparatorun Yeni Giysileri","resim":"🤴 👗 👦","kaynak":"H. C. Andersen masalından uyarlama","ders":"Doğruyu söylemek cesaret ister.","sayfalar":["Bir zamanlar yeni giysilere bayılan bir imparator vardı. Her saat başı elbise değiştirir, bütün parasını kıyafetlere harcardı. Ülkesinin dertleriyle ilgilenmez, aynanın karşısından ayrılmazdı.","Bir gün şehre iki dolandırıcı geldi. \"Biz dünyanın en güzel kumaşını dokuruz,\" dediler. \"Ama bu kumaşın sihirli bir özelliği var. Akılsız olanlar ve işini iyi yapmayanlar onu göremez.\" İmparator çok heyecanlandı.","İmparator dolandırıcılara bir sandık altın verdi. Dolandırıcılar boş tezgâhların başına oturdular ve sanki kumaş dokuyormuş gibi yaptılar. Gece gündüz çalışıyor gibi görünüyorlardı. Ama tezgâhlarda hiçbir şey yoktu.","İmparator kumaşı görmesi için en akıllı vezirini gönderdi. Vezir baktı, baktı ama hiçbir şey göremedi. \"Eyvah! Akılsız olduğumu düşünecekler,\" diye korktu. \"Ne güzel desenler, ne harika renkler!\" dedi.","Sonunda imparator kendisi geldi. O da hiçbir şey göremedi. Ama \"akılsız\" sanılmaktan korktu. \"Muhteşem! Hayatımda gördüğüm en güzel kumaş!\" dedi. Bütün saray halkı da hiçbir şey görmediği hâlde kumaşı övdü.","Dolandırıcılar havada makaslarını kesiyormuş gibi oynattılar, iğneleriyle dikiyormuş gibi yaptılar. Sonunda, \"Giysiler hazır!\" dediler. İmparatora görünmez elbiseyi giydirir gibi yaptılar. İmparator aynanın karşısında döndü durdu.","Ertesi gün büyük bir tören yapıldı. İmparator yeni giysileriyle sokaklarda yürüdü. Halk da akılsız sanılmaktan korkuyordu. Herkes, \"Ne güzel giysiler!\" diye bağırdı. Ama kimse doğruyu söyleyemiyordu.","Kalabalığın arasındaki küçük bir çocuk birden bağırdı: \"Ama imparatorun üstünde hiçbir şey yok!\" Herkes sustu. Sonra bütün halk, \"Çocuk doğru söylüyor!\" diye fısıldaştı. İmparator utandı. Dolandırıcılar ise çoktan altınlarla kaçmıştı. İmparator o günden sonra gösterişi bırakıp ülkesiyle ilgilenmeye başladı."],"sorular":[["İmparator en çok neyi severdi?","Yeni giysileri",["Kitapları","Atları"]],["Dolandırıcılar kumaş için ne dedi?","Akılsızlar göremez",["Çok ucuz","Suda erir"]],["Doğruyu kim söyledi?","Küçük bir çocuk",["Vezir","Dolandırıcılar"]],["Halk neden susuyordu?","Akılsız sanılmaktan korkuyordu",["Kumaşı görüyordu","Uykuluydu"]]]},
  {"id":"k26","baslik":"Parmak Kız","resim":"👧🌷 🐸 🐦","kaynak":"H. C. Andersen masalından uyarlama","ders":"İyilik yapan, iyilik bulur.","sayfalar":["Bir kadın çocuk sahibi olmayı çok istiyordu. Bir gün bahçesine bir tohum ekti. Tohumdan kocaman, kırmızı bir lale açtı. Lalenin yaprakları açılınca içinde başparmak kadar minik bir kız oturuyordu. Kadın ona Parmak Kız adını verdi.","Parmak Kız ceviz kabuğundan bir beşikte uyuyor, bir tabak suyun üstünde yaprak kayıkla geziyordu. Çok güzel şarkı söylüyordu. Ama bir gece pencereden bir kurbağa girdi. \"Bu kız oğluma eş olsun,\" dedi ve beşiği alıp götürdü.","Kurbağa Parmak Kız'ı derenin ortasındaki bir nilüfer yaprağına bıraktı. Parmak Kız ağladı. Suyun altındaki küçük balıklar ona acıdı. Nilüfer yaprağının sapını kemirip kopardılar. Yaprak, Parmak Kız'ı alıp uzaklara götürdü.","Yaz boyunca Parmak Kız ormanda yalnız yaşadı. Çiçeklerin balını içti, yaprakların üstündeki çiğle yıkandı. Ama kış gelince her yer buz tuttu. Parmak Kız aç ve üşümüştü. Bir tarla faresinin kapısını çaldı.","Tarla faresi onu içeri aldı. Parmak Kız da ona ev işlerinde yardım etti. Bir gün yer altındaki tünelde soğuktan donmuş bir kırlangıç buldu. Herkes onun öldüğünü düşündü. Ama Parmak Kız kırlangıcın kalbinin hâlâ attığını duydu.","Parmak Kız her gece gizlice kırlangıcın yanına gitti. Onu ottan bir battaniyeyle örttü, gagasına su damlattı. Kırlangıç yavaş yavaş iyileşti. İlkbahar gelince, \"Benimle gel, seni sıcak ülkelere götüreyim,\" dedi.","Parmak Kız kırlangıcın sırtına bindi. Dağların, denizlerin üstünden uçtular. Sonunda çiçeklerle dolu, güneşli bir vadiye indiler. Her çiçeğin içinde Parmak Kız kadar minik bir insan yaşıyordu. Hepsi onu sevinçle karşıladı.","Çiçek halkı Parmak Kız'a ışıl ışıl kanatlar hediye etti. Artık o da uçabiliyordu. Kırlangıç her yıl ona uğradı ve bu hikâyeyi bütün dünyaya şarkılarla anlattı. Parmak Kız, iyiliğinin karşılığını en güzel şekilde bulmuştu."],"sorular":[["Parmak Kız nereden çıktı?","Bir lalenin içinden",["Bir yumurtadan","Bir kutudan"]],["Parmak Kız'ı kim kaçırdı?","Kurbağa",["Kırlangıç","Fare"]],["Parmak Kız kime yardım etti?","Donmuş bir kırlangıca",["Bir balığa","Bir kediye"]],["Kırlangıç onu nereye götürdü?","Çiçeklerle dolu bir vadiye",["Denizin dibine","Bir saraya"]]]},
  {"id":"k27","baslik":"Külkedisi","resim":"👧 👠 🎃 🕛","kaynak":"Charles Perrault masalından uyarlama","ders":"İyi kalpli olmak her şeyden değerlidir.","sayfalar":["Bir zamanlar iyi kalpli bir kız vardı. Annesi ölmüş, babası yeniden evlenmişti. Üvey annesi ve iki üvey kız kardeşi ona çok kötü davranıyordu. Bütün ev işlerini ona yaptırıyor, ocağın külleri arasında yatırıyorlardı. Bu yüzden ona Külkedisi diyorlardı.","Bir gün saraydan bir haberci geldi. Kral, prens için büyük bir balo veriyordu ve ülkedeki bütün genç kızları davet ediyordu. Üvey kardeşler en güzel elbiselerini giydiler. Külkedisi'ne ise, \"Senin giyecek elbisen bile yok,\" diyerek güldüler.","Herkes baloya gidince Külkedisi bahçede ağlamaya başladı. Birden önünde ışıklar içinde bir peri belirdi. \"Ağlama, sen de baloya gideceksin,\" dedi. Sihirli değneğiyle bir balkabağına dokundu. Balkabağı altın bir arabaya dönüştü!","Peri altı fareyi beyaz atlara, bir sıçanı arabacıya çevirdi. Sonra değneğini Külkedisi'ne dokundurdu. Eski elbisesi ışıl ışıl bir balo elbisesine dönüştü. Ayaklarında cam ayakkabılar parlıyordu. \"Ama gece yarısından önce dönmelisin. O saatte büyü bozulacak,\" dedi peri.","Külkedisi baloya girince herkes ona baktı. Prens onu dansa davet etti. Bütün gece birlikte dans ettiler, sohbet ettiler. Külkedisi o kadar mutluydu ki zamanın nasıl geçtiğini anlamadı. Birden saat on ikiyi çalmaya başladı!","Külkedisi koşarak saraydan çıktı. Merdivenlerden inerken bir cam ayakkabısı ayağından çıktı. Ama geri dönüp alacak vakti yoktu. Saat on ikiyi vurduğunda arabası yeniden balkabağı, elbisesi yeniden eski elbisesi olmuştu.","Prens cam ayakkabıyı buldu. \"Bu ayakkabı kimin ayağına olursa onu bulacağım,\" dedi. Saray görevlileri ev ev dolaştı. Ülkedeki bütün kızlar ayakkabıyı denedi. Üvey kardeşler de denedi ama ayakkabı onlara çok küçük geldi.","Sonunda görevli, \"Bu evde başka kız var mı?\" diye sordu. Külkedisi utanarak öne çıktı. Ayakkabıyı denedi ve ayakkabı tam ayağına oldu! Prens onu tanıdı. Külkedisi üvey kardeşlerini de affetti. İyi kalbi sayesinde herkesin sevgisini kazandı."],"sorular":[["Kıza neden Külkedisi diyorlardı?","Küller arasında yattığı için",["Kedisi olduğu için","Gri giyindiği için"]],["Peri balkabağını neye çevirdi?","Altın bir arabaya",["Bir saraya","Bir ata"]],["Büyü ne zaman bozulacaktı?","Gece yarısı",["Sabah","Öğlen"]],["Prens Külkedisi'ni nasıl buldu?","Cam ayakkabıyla",["Bir mektupla","Bir şarkıyla"]]]},
  {"id":"k28","baslik":"Nasreddin Hoca Göle Maya Çalıyor","resim":"🧔 🏞️ 🥛","kaynak":"Nasreddin Hoca fıkrasından uyarlama","ders":"Denemeye değer bir hayal, umut verir.","sayfalar":["Bir gün Nasreddin Hoca eşeğine binmiş, Akşehir'in yakınındaki gölün kenarında dolaşıyormuş. Hava çok güzelmiş. Göl masmavi parlıyor, kuşlar suyun üstünde uçuşuyormuş.","Hoca eşeğinden inmiş. Heybesinden bir kase yoğurt çıkarmış. Sonra göl kenarına diz çökmüş ve kaşık kaşık yoğurdu suya katmaya başlamış. Gölün suyunu da bir sopayla dikkatlice karıştırıyormuş.","O sırada oradan köylüler geçiyormuş. Hoca'nın ne yaptığını görünce durmuşlar. Biri merakla sormuş: \"Hocam, hayırdır? Ne yapıyorsun öyle?\" Hoca başını kaldırmadan, \"Göle maya çalıyorum,\" demiş.","Köylüler birbirlerine bakıp gülmüşler. \"Hocam, hiç göl maya tutar mı? Bu kadar suya bir kase yoğurt ne yapsın?\" demişler. Biri de \"Bütün gölü yoğurt mu yapacaksın?\" diye kahkaha atmış.","Hoca karıştırmaya devam etmiş. Sonra köylülere dönüp gülümsemiş. Köylüler cevabı merakla bekliyormuş. Hoca sakin sakin sopasını yere bırakmış ve gözlerini göle dikmiş.","\"Ya tutarsa?\" demiş Hoca. \"Tutarsa bütün köyün yoğurdu olur. Tutmazsa da bir kase yoğurt gider. Denemeden bilemeyiz ki!\" Köylüler bu söze bir şey diyememişler.","O günden sonra köylüler zor bir işe başlarken hep Hoca'nın sözünü hatırlamışlar. Biri bir tarla ekecekken, biri bir ev yapacakken \"Ya tutarsa!\" demişler. Bu söz, umudu ve denemeyi anlatan bir atasözü gibi olmuş.","Bugün de bir şeyi denerken \"Ya tutarsa!\" deriz. Çünkü bazen herkesin güldüğü bir fikir, büyük bir buluşun ilk adımı olabilir. Nasreddin Hoca belki göle maya tutturamadı ama bize umudu ve cesareti öğretti. Sen de bugün denemekten korktuğun bir şeyi düşün. Belki bir resim, belki yeni bir oyun, belki de zor bir soru. Hoca gibi gülümse ve kendine sor: Ya tutarsa?"],"sorular":[["Hoca göle ne katıyordu?","Yoğurt",["Süt","Şeker"]],["Köylüler ne yaptı?","Hoca'ya güldüler",["Ona yardım ettiler","Gölde yüzdüler"]],["Hoca'nın cevabı neydi?","Ya tutarsa!",["Bilmiyorum","Şaka yaptım"]],["Bu fıkra bize ne öğretir?","Umut edip denemeyi",["Gölleri kirletmeyi","Yoğurt yapmayı"]]]}
];
